.pricing { padding: 6rem 0 7rem; }
.pricing__head { text-align: center; }
.pricing__head h2 { font-size: clamp(2rem, 3.2vw, 2.75rem); }
.pricing__head p { margin-top: .75rem; color: var(--ink-2); }
