/* Afterword landing. Tokens: zinc neutrals, one signal-orange accent.
   Radius rule: controls (buttons, checkboxes, chips) 8px; surfaces (cards, panels) 14px. */
:root {
  --bg: #f6f6f4;
  --surface: #fdfdfc;
  --surface-2: #ececea;
  --ink: #18181b;
  --ink-2: #52525b;
  --line: #dcdcd8;
  --accent: #c2410c;
  --accent-ink: #fdfdfc;
  --accent-soft: #fbe6da;
  --mark: #fde3d2;
  --shadow: 0 1px 0 rgb(24 24 27 / .04), 0 18px 40px -18px rgb(68 40 20 / .22);

  --font: "Schibsted Grotesk", ui-sans-serif, system-ui, sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, "SFMono-Regular", monospace;
  --r-control: 8px;
  --r-surface: 14px;
  --ease: cubic-bezier(.16, 1, .3, 1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #111113;
    --surface: #1a1a1d;
    --surface-2: #232327;
    --ink: #f2f2ef;
    --ink-2: #a1a1aa;
    --line: #2e2e33;
    --accent: #fb8a4c;
    --accent-ink: #1a0d05;
    --accent-soft: #3a2116;
    --mark: #4a2a18;
    --shadow: 0 1px 0 rgb(255 255 255 / .03), 0 24px 48px -20px rgb(0 0 0 / .6);
  }
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1.0625rem;
  line-height: 1.6;
