1	// Scroll reveal via IntersectionObserver and the live counter in the hero sample.
2	(function () {
3	  var reveals = document.querySelectorAll('.reveal');
4	  if ('IntersectionObserver' in window) {
5	    var io = new IntersectionObserver(function (entries) {
6	      entries.forEach(function (entry) {
7	        if (entry.isIntersecting) {
8	          entry.target.classList.add('is-in');
9	          io.unobserve(entry.target);
10	        }
11	      });
12	    }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
13	    reveals.forEach(function (el) { io.observe(el); });
14	  } else {
15	    reveals.forEach(function (el) { el.classList.add('is-in'); });
16	  }
17	
18	  var boxes = document.querySelectorAll('.task input[type="checkbox"]');
19	  var count = document.querySelector('[data-count]');
20	  if (!count || !boxes.length) return;
21	  function update() {
22	    var done = 0;
23	    boxes.forEach(function (b) { if (b.checked) done += 1; });
24	    count.textContent = done + ' of ' + boxes.length + ' done';
25	  }
26	  boxes.forEach(function (b) { b.addEventListener('change', update); });
27	  update();
28	})();
