134	.tasks { background: var(--surface-2); padding: 1rem 1.25rem 1.25rem; }
135	.tasks__label { display: flex; justify-content: space-between; font-weight: 600; font-size: .9375rem; margin-bottom: .625rem; }
136	.tasks__count { font: 400 .8125rem/1.7 var(--mono); color: var(--ink-2); }
137	.tasks ul { list-style: none; margin: 0; padding: 0; display: grid; gap: .5rem; }
138	.task {
139	  display: grid; grid-template-columns: 1fr auto auto; gap: .875rem; align-items: center;
140	  background: var(--surface); border: 1px solid var(--line); border-radius: var(--r-control);
141	  padding: .625rem .75rem; font-size: .9375rem;
142	}
143	.task label { display: flex; align-items: center; gap: .625rem; cursor: pointer; min-height: 44px; margin-block: -.5rem; }
144	.task input {
145	  appearance: none; margin: 0; flex: none;
146	  width: 20px; height: 20px; border-radius: 6px;
147	  border: 1.5px solid var(--ink-2); background: var(--surface);
148	  display: grid; place-items: center; cursor: pointer;
149	  transition: background-color .15s, border-color .15s;
150	}
151	.task input::after {
152	  content: ""; width: 10px; height: 6px;
153	  border: solid var(--accent-ink); border-width: 0 0 2px 2px;
154	  transform: translateY(-1px) rotate(-45deg) scale(0);
155	  transition: transform .2s var(--ease);
156	}
157	.task input:checked { background: var(--accent); border-color: var(--accent); }
158	.task input:checked::after { transform: translateY(-1px) rotate(-45deg) scale(1); }
159	.task input:checked + .task__text { text-decoration: line-through; color: var(--ink-2); }
160	.task__who { font-weight: 500; font-size: .875rem; }
161	.task__due { font: 400 .8125rem/1 var(--mono); color: var(--ink-2); white-space: nowrap; }
162	
163	/* Features */
164	.features { padding: 6rem 0; border-top: 1px solid var(--line); }
165	.features__grid {
166	  display: grid; gap: 1.25rem;
167	  grid-template-columns: 1.1fr 1fr 1fr;
168	  grid-template-areas:
169	    "intro lead lead"
170	    "intro a b"
171	    "wide wide wide";
172	}
173	.features__intro { grid-area: intro; padding-right: 2rem; align-self: start; position: sticky; top: 100px; }
174	.features__intro h2 { font-size: clamp(2rem, 3.2vw, 2.75rem); }
175	.features__intro p { margin-top: 1.125rem; color: var(--ink-2); max-width: 38ch; }
176	.feature { padding: 1.75rem; border-radius: var(--r-surface); border: 1px solid var(--line); background: var(--surface); }
177	.feature h3 { font-size: 1.25rem; }
178	.feature p { margin-top: .625rem; color: var(--ink-2); max-width: 52ch; }
179	.feature:nth-of-type(2) { grid-area: a; }
180	.feature:nth-of-type(3) { grid-area: b; }
181	.feature--lead { grid-area: lead; background: var(--accent-soft); border-color: transparent; }
182	.feature--lead p { color: var(--ink); opacity: .8; }
183	.feature--wide {
184	  grid-area: wide;
185	  display: grid; grid-template-columns: 1fr 1.4fr; gap: 2rem; align-items: baseline;
186	  background: var(--surface-2); border-color: transparent;
187	}
188	.feature--wide p { margin-top: 0; }
189	
190	.parse { margin-top: 1.5rem; display: flex; flex-wrap: wrap; align-items: center; gap: .75rem; }
191	.parse__in, .parse__out { font: 500 .875rem/1 var(--mono); padding: .625rem .75rem; border-radius: var(--r-control); }
192	.parse__in { background: var(--surface); color: var(--ink-2); }
193	.parse__out { background: var(--accent); color: var(--accent-ink); }
194	.parse__arrow { color: var(--accent); font-weight: 600; }
195	
196	/* Testimonials */
197	.quotes { padding: 6rem 0; background: var(--surface); border-block: 1px solid var(--line); }
198	.quotes__title { font-size: clamp(1.75rem, 2.6vw, 2.25rem); max-width: 22ch; }
199	.quotes__grid { margin-top: 3.5rem; display: grid; grid-template-columns: repeat(12, 1fr); gap: 2rem; }
200	.quote { margin: 0; align-self: start; grid-column: 1 / span 6; padding-left: 1.5rem; border-left: 3px solid var(--accent); }
201	.quote--offset { grid-column: 7 / span 6; margin-top: 5rem; }
202	.quote blockquote { margin: 0; }
203	.quote blockquote p { font-size: clamp(1.25rem, 1.8vw, 1.5rem); line-height: 1.4; letter-spacing: -0.01em; font-weight: 500; max-width: 34ch; }
204	.quote figcaption { margin-top: 1.25rem; display: grid; gap: .125rem; }
205	.quote__name { font-weight: 600; }
206	.quote__role { color: var(--ink-2); font-size: .9375rem; }
207	
208	/* Pricing */
209	.pricing { padding: 6rem 0 7rem; }
210	.pricing__head { text-align: center; }
211	.pricing__head h2 { font-size: clamp(2rem, 3.2vw, 2.75rem); }
212	.pricing__head p { margin-top: .75rem; color: var(--ink-2); }
213	.plans { margin: 3rem auto 0; max-width: 880px; display: grid; grid-template-columns: 1fr 1fr; gap: 1.25rem; align-items: stretch; }
214	.plan {
215	  display: flex; flex-direction: column;
216	  padding: 2rem; border-radius: var(--r-surface);
217	  border: 1px solid var(--line); background: var(--surface);
218	}
219	.plan--team { border: 2px solid var(--accent); box-shadow: var(--shadow); }
220	.plan h3 { font-size: 1.375rem; }
221	.plan__for { margin-top: .375rem; color: var(--ink-2); font-size: .9375rem; }
222	.plan__price { margin: 1.75rem 0 1.5rem; display: flex; align-items: baseline; gap: .625rem; }
223	.plan__amount { font-size: 3rem; font-weight: 650; letter-spacing: -0.03em; line-height: 1; }
224	.plan__per { color: var(--ink-2); font-size: .9375rem; }
225	.plan__list { list-style: none; margin: 0 0 2rem; padding: 1.5rem 0 0; border-top: 1px solid var(--line); display: grid; gap: .75rem; flex: 1; align-content: start; }
226	.plan__list li { position: relative; padding-left: 1.5rem; }
227	.plan__list li::before {
228	  content: ""; position: absolute; left: 0; top: .55em;
229	  width: 10px; height: 6px;
230	  border: solid var(--accent); border-width: 0 0 2px 2px;
231	  transform: rotate(-45deg);
232	}
233	
234	/* Signup */
235	.signup { padding: 0 0 7rem; }
236	.signup__inner {
237	  display: grid; grid-template-columns: 1fr 1.15fr; gap: 3rem; align-items: center;
238	  padding: 3rem; border-radius: var(--r-surface); background: var(--accent-soft);
239	}
240	.signup__copy h2 { font-size: clamp(1.75rem, 2.6vw, 2.25rem); }
241	.signup__copy p { margin-top: .625rem; color: var(--ink); opacity: .8; }
242	.field { display: grid; gap: .5rem; }
243	.field label { font-weight: 600; font-size: .9375rem; }
244	.field__row { display: flex; gap: .75rem; }
245	.field input {
246	  flex: 1; min-width: 0; min-height: 48px; padding: 0 1rem;
247	  font: 400 1rem/1 var(--font); color: var(--ink);
248	  background: var(--surface); border: 1px solid var(--ink-2); border-radius: var(--r-control);
249	}
250	.field input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
251	.field input[aria-invalid="true"] { border-color: var(--danger); }
252	.field__help { font-size: .875rem; color: var(--ink); opacity: .8; }
253	.field__error { font-size: .875rem; font-weight: 500; color: var(--danger); }
254	
255	/* Footer */
256	.footer { border-top: 1px solid var(--line); padding: 2rem 0; }
257	.footer__inner { display: flex; align-items: center; gap: 2rem; }
258	.footer__links { display: flex; gap: 1.5rem; list-style: none; margin: 0; padding: 0; }
259	.footer__links a { color: var(--ink-2); text-decoration: none; font-size: .9375rem; }
260	.footer__links a:hover { color: var(--ink); }
261	.footer__copy { margin-left: auto; color: var(--ink-2); font-size: .875rem; }
262	
263	/* Motion: hero load-in sequence, settle-on-scroll elsewhere. Transform only: content is never invisible,
264	   so a capture, print or stalled script still shows the full page. Only when the user allows motion. */
265	@media (prefers-reduced-motion: no-preference) {
266	  .enter { animation: rise .8s var(--ease) backwards; animation-delay: calc(var(--i) * 90ms); }
267	  .task { animation: rise .6s var(--ease) backwards; animation-delay: calc(500ms + var(--k) * 140ms); }
268	  .js .reveal { transform: translateY(18px); transition: transform .8s var(--ease); }
269	  .js .reveal.is-in { transform: none; }
270	}
271	@keyframes rise { from { transform: translateY(14px); } to { transform: none; } }
272	
273	/* Responsive */
274	@media (max-width: 960px) {
275	  .hero__grid { grid-template-columns: 1fr; gap: 3rem; }
276	  .hero h1 { max-width: 16ch; }
277	  .features__grid {
278	    grid-template-columns: 1fr 1fr;
279	    grid-template-areas: "intro intro" "lead lead" "a b" "wide wide";
280	  }
281	  .features__intro { position: static; padding-right: 0; }
282	  .feature--wide { grid-template-columns: 1fr; gap: .625rem; }
283	}
284	@media (max-width: 767px) {
285	  .wrap { width: calc(100% - 2rem); }
286	  .nav__inner { height: auto; flex-wrap: wrap; row-gap: 0; padding-top: .625rem; }
287	  .nav nav { order: 3; width: 100%; }
288	  .nav__links { gap: 1.25rem; }
289	  .nav__actions { gap: 1rem; }
290	  .hero { padding: 3rem 0 4rem; }
291	  .features, .quotes, .pricing { padding: 4.5rem 0; }
292	  .features__grid { grid-template-columns: 1fr; grid-template-areas: "intro" "lead" "a" "b" "wide"; }
293	  .quotes__grid { grid-template-columns: 1fr; gap: 2.5rem; margin-top: 2.5rem; }
294	  .quote, .quote--offset { grid-column: 1; margin-top: 0; }
295	  .plans { grid-template-columns: 1fr; }
296	  .signup { padding-bottom: 4.5rem; }
297	  .signup__inner { grid-template-columns: 1fr; gap: 1.75rem; padding: 1.75rem 1.25rem; }
298	  .field__row { flex-direction: column; }
299	  .task { grid-template-columns: 1fr auto; }
300	  .task__due { grid-column: 2; }
301	  .task__who { grid-column: 2; grid-row: 1; }
302	  .footer__inner { flex-wrap: wrap; gap: 1rem 1.5rem; }
303	  .footer__copy { margin-left: 0; width: 100%; }
304	}
